// Changes: Lower binary operands in order and stop when a path returns.
static IrOperand lower_binary(Ctx* ctx,
                              IrFunctionId function_id,
                              IrBlockId* block_id,
                              AstNode* node) {
  AstNode* left_node = ast_node_child(ctx, node, AST_BINARY_LEFT);
  AstNode* right_node = ast_node_child(ctx, node, AST_BINARY_RIGHT);

  // Lower the left operand first so side effects occur in source order.
  IrOperand left = lower_expression(ctx, function_id, block_id, left_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  IrOperand right = lower_expression(ctx, function_id, block_id, right_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  IrType type = ast_to_ir_data_type(ctx, ast_node_get_data_type(node));
  IrInstructionType instruction =
      binary_instruction(ctx, ast_node_get_type(node), type);

  return add_binary(ctx, function_id, *block_id, instruction, type, left,
                    right);
}

