// Changes: Lower unary operators on paths that continue after the operand.
static IrOperand lower_unary(Ctx* ctx,
                             IrFunctionId function_id,
                             IrBlockId* block_id,
                             AstNode* node) {
  AstNode* operand_node = ast_node_child(ctx, node, AST_UNARY_OPERAND);
  IrOperand operand =
      lower_expression(ctx, function_id, block_id, operand_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  switch (ast_node_get_type(node)) {
    case AST_NODE_NOT:
      return add_unary(ctx, function_id, *block_id, IR_INST_NOT, IR_BOOL,
                       operand);
    case AST_NODE_INT_TO_DOUBLE:
      return add_unary(ctx, function_id, *block_id, IR_INST_INT2DOUBLE,
                       IR_DOUBLE, operand);
    case AST_NODE_NEG:
      // Multiplication by -1.0 also flips the sign of a floating-point zero.
      if (ast_node_get_data_type(node) == AST_DATA_TYPE_DOUBLE)
        return add_binary(ctx, function_id, *block_id, IR_INST_MUL, IR_DOUBLE,
                          double_operand(-1.0), operand);
      return add_binary(ctx, function_id, *block_id, IR_INST_SUB, IR_INT,
                        int_operand(0), operand);
    default:
      THROW(E_INTERNAL_ERROR, "Unexpected unary expression");
      return unit_operand();  // Unreachable
  }
}

