static IrOperand add_call(Ctx* ctx,
                          IrFunctionId function_id,
                          IrBlockId block_id,
                          IrInstruction instruction) {
  IrValueId value = ir_add_instruction(ctx, function_id, block_id, instruction);

  return value == IR_INVALID_ID ? unit_operand() : value_operand(value);
}

