// Changes: Add static lower_concat helper to lower AST_NODE_CONCAT operands and
// emit IR_FX_LIST_CONCAT.
/**
 * @brief Lowers a list concatenation expression to IR_FX_LIST_CONCAT call
 * @param ctx Compiler context
 * @param function_id Enclosing IR function ID
 * @param block_id Current IR block ID
 * @param node AST_NODE_CONCAT node to lower
 * @return IR operand holding the concatenated list, or unit_operand() if
 * terminated
 */
static IrOperand lower_concat(Ctx* ctx,
                              IrFunctionId function_id,
                              IrBlockId* block_id,
                              AstNode* node) {
  AstNode* left_node = ast_node_child(ctx, node, AST_BINARY_LEFT);
  AstNode* right_node = ast_node_child(ctx, node, AST_BINARY_RIGHT);

  IrOperand left = lower_expression(ctx, function_id, block_id, left_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  IrOperand right = lower_expression(ctx, function_id, block_id, right_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  IrOperand args[2] = {left, right};
  return add_call(ctx, function_id, *block_id,
                  (IrInstruction){.type = IR_INST_CALL,
                                  .result_type = IR_ARRAY,
                                  .operands.call = {.type = IR_FX_LIST_CONCAT,
                                                    .id = IR_INVALID_ID,
                                                    .args = args,
                                                    .arg_count = 2}});
}

