  // account.  Compute the default step accordingly and remove unused if."
  // Changes: Append default step=1 for 2-argument IR_FX_LIST_RANGE calls in the
  // standard call path.
  bool default_step = builtin &&
                      (IrFunctionType)symbol->ir_index == IR_FX_LIST_RANGE &&
                      count == 2;
  size_t arg_count = default_step ? 3 : count;
  IrInstruction instruction = {
      .type = IR_INST_CALL,
      .result_type = result_type,
      .operands.call = {
          .type = builtin ? (IrFunctionType)symbol->ir_index : IR_FX_USER,
          .id = builtin ? IR_INVALID_ID : symbol->ir_index,
          .arg_count = arg_count}};

