  // step (check for invalid IDs).. Emit (IR_ARRAY)IR_FX_RANGE_TO_LIST and args
  // matching codegen." Changes: Handle range receiver in lower_member by
  // lowering start, end, step and emitting IR_FX_RANGE_TO_LIST.
  AstNodeType receiver_kind = ast_node_get_type(receiver_node);
  if (receiver_kind == AST_NODE_RANGE_TO ||
      receiver_kind == AST_NODE_RANGE_UNTIL) {
    AstNode* start_node = ast_node_child(ctx, receiver_node, 0);
    AstNode* end_node = ast_node_child(ctx, receiver_node, 1);
    AstNode* step_node = ast_node_child(ctx, receiver_node, AST_RANGE_STEP);

    IrOperand start = lower_expression(ctx, function_id, block_id, start_node);
    if (*block_id == IR_INVALID_ID)
      return unit_operand();

    IrOperand end = lower_expression(ctx, function_id, block_id, end_node);
    if (*block_id == IR_INVALID_ID)
      return unit_operand();

    IrOperand step = int_operand(1);
    if (ast_node_get_type(step_node) != AST_NODE_NONE)
      step = lower_expression(ctx, function_id, block_id, step_node);
    if (*block_id == IR_INVALID_ID)
      return unit_operand();

    IrOperand args[4] = {start, end, step,
                         bool_operand(receiver_kind == AST_NODE_RANGE_TO)};
    return add_call(
        ctx, function_id, *block_id,
        (IrInstruction){.type = IR_INST_CALL,
                        .result_type = IR_ARRAY,
                        .operands.call = {.type = IR_FX_RANGE_TO_LIST,
                                          .id = IR_INVALID_ID,
                                          .args = args,
                                          .arg_count = 4}});
  }

  IrOperand receiver =
      lower_expression(ctx, function_id, block_id, receiver_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  // Floor is an IR instruction. Other members are calls on the receiver.
  if (strcmp(ast_node_get_name(node), "floor") == 0)
    return add_unary(ctx, function_id, *block_id, IR_INST_FLOOR, IR_DOUBLE,
                     receiver);

  // AI generated by: Antigravity / Gemini 4 Hydrogen
